// Differential checks of PrimOpInt03Configurable-pbo.js against Lean, generated by leanscript --check
import * as M from "./PrimOpInt03Configurable-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
// a recursive union: as `showUnion`, the fields marked in `rec[tag]` (the type itself) printed
// the same way, one level less deep (`…` at depth 0, as `showExpr` cuts it in Lean)
function showTree(v, rec, d) {
  if (d === 0) return "…";
  if (typeof v === "number") return v + "()";
  const r = rec[v.tag] || [];
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++)
    fs.push(r[i - 1] ? showTree(v["_" + i], rec, d - 1) : show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("TestNat$test1", () => M.TestNat$test1, "4000000000", false);
check("TestNat$test2", () => M.TestNat$test2, "0", false);
check("TestNat$test4(0)", () => M.TestNat$test4(0), "4000000000", false);
check("TestNat$test4(1)", () => M.TestNat$test4(1), "4000000001", false);
check("TestNat$test4(2)", () => M.TestNat$test4(2), "4000000002", false);
check("TestNat$test4(5)", () => M.TestNat$test4(5), "4000000005", false);
check("TestNat$test4(13)", () => M.TestNat$test4(13), "4000000013", false);
check("TestInt$test1", () => M.TestInt$test1, "4000000000", false);
check("TestInt$test2", () => M.TestInt$test2, "-4000000000", false);
check("TestInt$test4(-7)", () => M.TestInt$test4(-7), "3999999993", false);
check("TestInt$test4(-1)", () => M.TestInt$test4(-1), "3999999999", false);
check("TestInt$test4(0)", () => M.TestInt$test4(0), "4000000000", false);
check("TestInt$test4(1)", () => M.TestInt$test4(1), "4000000001", false);
check("TestInt$test4(2)", () => M.TestInt$test4(2), "4000000002", false);
check("TestInt$test4(3)", () => M.TestInt$test4(3), "4000000003", false);
check("TestInt$test4(12)", () => M.TestInt$test4(12), "4000000012", false);

console.log(`PrimOpInt03Configurable-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
